<?php
namespace ZinCelestial\Platform\Logging; defined('ABSPATH')||exit;
final class JobLogger{const OPTION='zcp_job_log';const LIMIT=200;public static function add(string $level,string $message,array $context=array()):void{$rows=(array)get_site_option(self::OPTION,array());$rows[]=array('time'=>time(),'level'=>sanitize_key($level),'message'=>sanitize_text_field($message),'context'=>self::clean($context));$rows=array_slice($rows,-self::LIMIT);update_site_option(self::OPTION,$rows);}public static function all():array{return (array)get_site_option(self::OPTION,array());}public static function prune(int $days=14):void{$cut=time()-max(1,$days)*DAY_IN_SECONDS;update_site_option(self::OPTION,array_values(array_filter(self::all(),fn($r)=>(int)($r['time']??0)>=$cut)));}private static function clean(array $v):array{$o=array();foreach($v as $k=>$x)$o[sanitize_key((string)$k)]=is_scalar($x)?sanitize_text_field((string)$x):'[complex]';return $o;}}
